# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import rounded_labels


class RoundingTests(unittest.TestCase):
    def test_label_after_snapping(self):
        span = Span(9 * 60 + 2, 17 * 60 + 14)
        self.assertEqual(
            rounded_labels([span], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_halves_round_up(self):
        self.assertEqual(
            rounded_labels([Span(68, 180)], 15),
            ["01:15-03:00 (1h 45m)"]
        )

    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45):
            with self.assertRaises(ValueError):
                rounded_labels([Span(60, 120)], step)

    def test_span_that_collapses_raises(self):
        with self.assertRaises(ValueError):
            rounded_labels([Span(61, 64)], 15)


if __name__ == "__main__":
    unittest.main()
